Create a `TooltipContext` to manage the state of the tooltip and a `TooltipProvider` to wrap the tooltip component and provide the context to its children.

```jsx
import React, { createContext, useContext, useState } from 'react';

const TooltipContext = createContext();

export const TooltipProvider = ({ children }) => {
  const [tooltip, setTooltip] = useState(null);

  const closeTooltip = () => {
    setTooltip(null);
  };

  const openTooltip = (content) => {
    setTooltip({ content, x: event.clientX, y: event.clientY });
  };

  return (
    <TooltipContext.Provider value={{ tooltip, openTooltip, closeTooltip }}>
      {children}
      {tooltip && <Tooltip {...tooltip} />}
    </TooltipContext.Provider>
  );
};

export const useTooltip = () => useContext(TooltipContext);
```

Create the `Tooltip` component that accepts the `content`, `x`, and `y` props and uses them to render the tooltip.

```jsx
import React, { useEffect } from 'react';

const Tooltip = ({ content, x, y }) => {
  useEffect(() => {
    const tooltip = document.getElementById('tooltip');
    tooltip.style.left = `${x}px`;
    tooltip.style.top = `${y}px`;
  }, [x, y]);

  return (
    <div id="tooltip" className="tooltip">
      <div className="tooltip-arrow" />
      <div className="tooltip-content">{content}</div>
    </div>
  );
};

export default Tooltip;
```

Now, you can use the `TooltipProvider` and `useTooltip` hook in your components to open and close tooltips.

```jsx
import React, { useEffect } from 'react';
import TooltipProvider from '../TooltipContext';
import { useTooltip } from '../TooltipContext';

const MyComponent = () => {
  const { openTooltip, closeTooltip } = useTooltip();

  const handleMouseOver = (event) => {
    openTooltip('This is the tooltip content');
  };

  const handleMouseLeave = () => {
    closeTooltip();
  };

  return (
    <div onMouseOver={handleMouseOver} onMouseLeave={handleMouseLeave}>
      Hover over me to see the tooltip
    </div>
  );
};

export default function App() {
  return (
    <TooltipProvider>
      <MyComponent />
    </TooltipProvider>
  );
}
```

