export const BOOK_AUTHOR = 'Author';

// displayBook.js
import { BOOK_TITLE, BOOK_AUTHOR } from './messages';

function displayBook(book, messages) {
  console.log(`${messages[BOOK_TITLE]}: ${book.title}, ${messages[BOOK_AUTHOR]}: ${book.author}`);
}
```

