```java
import java.beans.IntrospectionException;
import java.beans.PropertyDescriptor;
import java.lang.reflect.InvocationTargetException;
import java.util.HashMap;
import java.util.Map;

public class ObjectToDtoConverter {

    public static <T, D> Map<String, Object> convert(T source, Class<D> destinationClass) {
        Map<String, Object> result = new HashMap<>();

        try {
            for (PropertyDescriptor property : new PropertyDescriptor[source.getClass().getDeclaredFields().length]) {
                property = new PropertyDescriptor(source.getClass().getDeclaredField(property.getName()).getName(), source.getClass());
                result.put(property.getName(), property.getReadMethod().invoke(source));
            }

            D dto = destinationClass.newInstance();
            for (Map.Entry<String, Object> entry : result.entrySet()) {
                PropertyDescriptor property = new PropertyDescriptor(entry.getKey(), destinationClass);
                property.getWriteMethod().invoke(dto, entry.getValue());
            }

            return result;
        } catch (IntrospectionException | InstantiationException | IllegalAccessException | InvocationTargetException e) {
            throw new RuntimeException(e);
        }
    }
}
```

In this example, the `convert` method takes an object and a DTO class as parameters. It first converts the object to a Map, then it creates a new instance of the DTO class and populates it with the data from the Map.

