            selector: 'h2',
        },
        content: {
            type: 'string',
            source: 'html',
            selector: 'p',
        },
        imageAlt: {
            attribute: 'alt',
            selector: '.my-image',
        },
        imageUrl: {
            attribute: 'src',
            selector: '.my-image',
        },
    },
    edit({ attributes, setAttributes }) {
        const handleMediaUpload = (image) => {
            setAttributes({ imageUrl: image.url, imageAlt: image.alt });
        };

        return (
            <div className="my-custom-block">
                <InspectorControls>
                    <MediaUpload
                        onSelect={handleMediaUpload}
                        type="image"
                        value={attributes.imageId}
                        render={({ open }) => (
                            <Button onClick={open} className="button button-large">
                                Add Image
                            </Button>
                        )}
                    />
                </InspectorControls>
                <RichText
                    tagName="h2"
                    placeholder="Your heading"
                    value={attributes.title}
                    onChange={(value) => setAttributes({ title: value })}
                />
                <RichText
                    tagName="p"
                    placeholder="Your paragraph"
                    value={attributes.content}
                    onChange={(value) => setAttributes({ content: value })}
                />
                <div className="my-image-container">
                    { attributes.imageUrl ? (
                        <img src={ attributes.imageUrl } alt={ attributes.imageAlt } className="my-image" />
                    ) : (
                        <div className="my-image-placeholder">Add Image</div>
                    )}
                </div>
            </div>
        );
    },
    save({ attributes }) {
        const { title, content, imageUrl, imageAlt } = attributes;

        return (
            <div className="my-custom-block">
                <h2>{ title }</h2>
                <p>{ content }</p>
                <div className="my-image-container">
                    { imageUrl ? (
                        <img src={ imageUrl } alt={ imageAlt } className="my-image" />
                    ) : null}
                </div>
            </div>
        );
    },
});
