Here's a simple example of how you can read a SQL query from a file and execute it using JDBC in a Spring Boot application:

1. First, create a `sql` folder in your resources directory and place your SQL query in a file named `query.sql`.

2. Create a `QueryService` class that reads the SQL query from the file and executes it using JDBC:

```java
import java.io.File;
import java.io.FileReader;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Statement;
import java.util.ArrayList;
import java.util.List;

public class QueryService {

    private String url;
    private String user;
    private String password;

    public QueryService(String url, String user, String password) {
        this.url = url;
        this.user = user;
        this.password = password;
    }

    public List<String> executeQuery(String query) throws SQLException {
        List<String> results = new ArrayList<>();
        try (Connection connection = DriverManager.getConnection(url, user, password);
             Statement statement = connection.createStatement();
             ResultSet resultSet = statement.executeQuery(query)) {

            while (resultSet.next()) {
                results.add(resultSet.getString(1));
            }
        }
        return results;
    }

    public List<String> readQueryFromFile() throws SQLException, Exception {
        File file = new File("classpath:sql/query.sql");
        FileReader reader = new FileReader(file);
        StringBuilder query = new StringBuilder();
        int c;
        while ((c = reader.read()) != -1) {
            query.append((char) c);
        }
        return executeQuery(query.toString());
    }
}
```

